Perfecto. Dos errores, dos reglas: toda variable que deba reiniciarse por cada iteración del ciclo externo debe declararse e inicializarse DENTRO de ese ciclo.

```c
printf("Cantidad de clientes: ");
scanf("%d", &nClientes);
float totalGeneral = 0;
int contCliente = 1;

while (contCliente <= nClientes) {
    printf("\n=== Cliente #%d ===\n", contCliente);
    printf("Cantidad de productos: ");
    scanf("%d", &nProductos);

    float totalCliente = 0;    // se reinicia aqui
    int contProducto = 1;      // se reinicia aqui

    while (contProducto <= nProductos) {
        float precio;
        int cantidad;
        printf("  Producto #%d\n", contProducto);
        printf("    Precio unitario: ");
        scanf("%f", &precio);
        printf("    Cantidad: ");
        scanf("%d", &cantidad);
        totalCliente = totalCliente + (precio * cantidad);
        contProducto = contProducto + 1;
    }

    printf("Total del cliente #%d: %.2f\n", contCliente, totalCliente);
    totalGeneral = totalGeneral + totalCliente;
    contCliente = contCliente + 1;
}
printf("\nTotal general del supermercado: %.2f\n", totalGeneral);
```

¿Por qué totalGeneral se declara FUERA del ciclo de clientes?
